add_action( 'init', 'perfectpixel_disable_login_by_email' );
add_filter( 'woocommerce_get_username_from_email', '__return_false' );
add_filter( 'gettext', 'perfectpixel_login_username_label', 20, 3 );

function perfectpixel_disable_login_by_email() {
	remove_filter( 'authenticate', 'wp_authenticate_email_password', 20 );
}

function perfectpixel_login_username_label( $translation, $text, $domain ) {
	if ( 'default' === $domain && 'Username or Email Address' === $text && isset( $GLOBALS['pagenow'] ) && 'wp-login.php' === $GLOBALS['pagenow'] ) {
		return __( 'Username' );
	}
	return $translation;
}
